    yamlconfig = None
    try:
        if self._recent_pyyaml():
            # https://github.com/yaml/pyyaml/wiki/PyYAML-yaml.load(input)-Deprecation
            # only for 5.1+
            yamlconfig = yaml.load(open(configfile), Loader=yaml.FullLoader)
        else:
